FILES = {'apps/runner/src/gpt_trace_runner/tools.py': {'source_sha256': '8023c2c8cf8af877b429599e4d28cac25446dc63613475e6a7f0f9a7d32386f0', 'target_sha256': 'e197c560a61c2bd4174bff878c5fc4d6f1ee8c69e5f55dae9218f9443305b25f', 'target_text': 'from __future__ import annotations\n\nimport asyncio\n\nfrom playwright.async_api import Locator, Page\n\nfrom .exceptions import AppUnavailable, FatalUIState\nfrom .interaction import InteractionGuard\nfrom .models import BenchmarkTool\n\n# ChatGPT\'s @ mention autocomplete is the canonical App resolution path for the\n# runner. Selection is keyboard-native: the UI already highlights the resolved\n# App result, so Enter accepts it without relying on unstable popup DOM.\n#\n# No per-key delay is added here. The connected CloakBrowser session owns\n# humanization for normal Playwright keyboard events.\n\n\nasync def _select_app_via_mention(\n    page: Page,\n    *,\n    editor: Locator,\n    tool: BenchmarkTool,\n    interaction: InteractionGuard,\n    timeout_seconds: float,\n) -> None:\n    if tool.type != "app":\n        raise FatalUIState(f"unsupported benchmark tool type at runtime: {tool.type}")\n\n    await interaction.click(editor)\n    try:\n        # Contenteditable composers can contain several blocks. Ctrl+End keeps\n        # the benchmark prompt intact and appends the mention at the end.\n        await editor.press("Control+End")\n    except Exception:\n        pass\n\n    try:\n        before = await editor.inner_text()\n    except Exception:\n        before = ""\n\n    if before and not before.endswith((" ", "\\n")):\n        await page.keyboard.type(" ")\n\n    # Real key events are required to open ChatGPT\'s mention autocomplete.\n    # CloakBrowser applies the configured humanization to these Playwright\n    # keyboard events; do not layer a manual delay on top.\n    raw_mention = f"@{tool.name}"\n    await page.keyboard.type("@")\n    await asyncio.sleep(0.15)\n    await page.keyboard.type(tool.name)\n\n    # First prove that the exact raw mention query reached the composer.\n    deadline = asyncio.get_running_loop().time() + timeout_seconds\n    typed_rendered = ""\n    while asyncio.get_running_loop().time() < deadline:\n        try:\n            typed_rendered = await editor.inner_text()\n        except Exception:\n            typed_rendered = ""\n        if typed_rendered.rstrip().endswith(raw_mention):\n            break\n        await asyncio.sleep(0.05)\n    else:\n        raise AppUnavailable(\n            f"ChatGPT app mention query {raw_mention!r} was not reflected in the composer"\n        )\n\n    # The visible autocomplete already has the resolved App selected. Accept it\n    # exactly as a keyboard user does instead of trying to rediscover/click the\n    # popup item through unstable DOM selectors.\n    await page.keyboard.press("Enter")\n\n    # Accepted App mentions are structured composer nodes. Visibly, the raw\n    # \'@Name\' query becomes a mention chip whose text is \'Name\'. Since we append\n    # at the end, this suffix transition is a local invariant and does not\n    # depend on the popup DOM.\n    deadline = asyncio.get_running_loop().time() + timeout_seconds\n    while asyncio.get_running_loop().time() < deadline:\n        try:\n            rendered = await editor.inner_text()\n        except Exception:\n            rendered = ""\n        tail = rendered.rstrip()\n        if (\n            rendered != typed_rendered\n            and tail.endswith(tool.name)\n            and not tail.endswith(raw_mention)\n        ):\n            return\n        await asyncio.sleep(0.05)\n\n    raise AppUnavailable(\n        f"ChatGPT app {tool.name!r} was typed but Enter did not produce "\n        "an accepted App mention in the composer"\n    )\n\n\nasync def _clear_editor(editor: Locator, interaction: InteractionGuard) -> None:\n    """Clear the scratch composer used by the auth/App preflight."""\n    await interaction.click(editor)\n    await editor.press("Control+A")\n    await editor.press("Backspace")\n\n\nasync def assert_apps_available(\n    page: Page,\n    *,\n    editor: Locator,\n    tools: tuple[BenchmarkTool, ...],\n    interaction: InteractionGuard,\n    timeout_seconds: float,\n) -> None:\n    """Verify required Apps by actually resolving each one through \'@\'."""\n    seen: set[str] = set()\n    for tool in tools:\n        if tool.type != "app":\n            raise FatalUIState(f"unsupported benchmark tool type at runtime: {tool.type}")\n        if tool.name in seen:\n            continue\n        seen.add(tool.name)\n\n        try:\n            await _select_app_via_mention(\n                page,\n                editor=editor,\n                tool=tool,\n                interaction=interaction,\n                timeout_seconds=timeout_seconds,\n            )\n        finally:\n            # auth is only a preflight; do not leave scratch mentions behind.\n            try:\n                await page.keyboard.press("Escape")\n                await _clear_editor(editor, interaction)\n            except Exception:\n                pass\n\n\nasync def select_apps(\n    page: Page,\n    *,\n    editor: Locator,\n    tools: tuple[BenchmarkTool, ...],\n    interaction: InteractionGuard,\n    timeout_seconds: float,\n) -> None:\n    """Append each benchmark App as a real ChatGPT @ mention."""\n    for tool in tools:\n        await _select_app_via_mention(\n            page,\n            editor=editor,\n            tool=tool,\n            interaction=interaction,\n            timeout_seconds=timeout_seconds,\n        )\n'}, 'apps/runner/src/gpt_trace_runner/interaction.py': {'source_sha256': '4814678839a061b2a93002131ab3bd54b14c3b6485a7dd7c8724f90efb7e7a49', 'target_sha256': '0124f76a79f981a4ad82003dd1fdd90427cc23b599c19fb02be8f739eae914e8', 'target_text': 'from __future__ import annotations\n\nimport asyncio\nimport httpx\nfrom playwright.async_api import Locator, Page\n\nfrom .exceptions import ChatGPTUIError, ClipboardUnavailable, FatalUIState\n\n\nclass InteractionGuard:\n    """Drive visible controls while keeping focus and clipboard state coherent."""\n\n    def __init__(self, page: Page, *, clipboard_url: str, timeout_seconds: float) -> None:\n        self._page = page\n        self._clipboard_url = clipboard_url\n        self._timeout_ms = int(timeout_seconds * 1000)\n\n    async def ensure_page_focus(self) -> None:\n        try:\n            state = await self._page.evaluate(\n                "() => ({visible: document.visibilityState === \'visible\', focused: document.hasFocus()})"\n            )\n        except Exception as exc:\n            raise FatalUIState("could not inspect ChatGPT foreground state") from exc\n        if state.get("visible") and state.get("focused"):\n            return\n        await self._page.bring_to_front()\n        try:\n            await self._page.wait_for_function(\n                "() => document.visibilityState === \'visible\' && document.hasFocus()",\n                timeout=self._timeout_ms,\n            )\n        except Exception as exc:\n            raise FatalUIState("ChatGPT page did not obtain foreground focus") from exc\n\n    async def click(self, locator: Locator, *, timeout_ms: int | None = None) -> None:\n        await self.ensure_page_focus()\n        timeout = timeout_ms or self._timeout_ms\n        try:\n            await locator.wait_for(state="visible", timeout=timeout)\n            if not await locator.is_enabled():\n                raise ChatGPTUIError("target control is visible but disabled")\n            await locator.click(timeout=timeout)\n        except ChatGPTUIError:\n            raise\n        except Exception as exc:\n            raise ChatGPTUIError("browser UI click failed") from exc\n\n    async def type_text(\n        self,\n        locator: Locator,\n        text: str,\n        *,\n        clear_existing: bool = True,\n    ) -> None:\n        """Type benchmark text through real keyboard events.\n\n        CloakBrowser owns keyboard humanization. Newlines are entered with\n        Shift+Enter so a multiline prompt cannot submit before composition is\n        complete.\n        """\n        await self.ensure_page_focus()\n        try:\n            await locator.wait_for(state="visible", timeout=self._timeout_ms)\n            await self.click(locator, timeout_ms=self._timeout_ms)\n            if clear_existing:\n                await locator.press("Control+A")\n                await locator.press("Backspace")\n\n            expected = text.replace("\\r\\n", "\\n").replace("\\r", "\\n")\n            for index, line in enumerate(expected.split("\\n")):\n                if index:\n                    await self._page.keyboard.press("Shift+Enter")\n                if line:\n                    await self._page.keyboard.type(line)\n\n            deadline = asyncio.get_running_loop().time() + (self._timeout_ms / 1000)\n            rendered = ""\n            while asyncio.get_running_loop().time() < deadline:\n                rendered = (\n                    await locator.inner_text(timeout=self._timeout_ms)\n                ).replace("\\r\\n", "\\n").replace("\\r", "\\n")\n                if rendered == expected:\n                    return\n                await asyncio.sleep(0.05)\n        except ChatGPTUIError:\n            raise\n        except Exception as exc:\n            raise ChatGPTUIError("could not type benchmark prompt") from exc\n\n        raise ChatGPTUIError(\n            "composer text differs from benchmark prompt after keyboard entry"\n        )\n\n    async def _set_system_clipboard(self, text: str) -> None:\n        try:\n            async with httpx.AsyncClient(timeout=10.0) as client:\n                response = await client.post(\n                    self._clipboard_url,\n                    content=text.encode("utf-8"),\n                    headers={"content-type": "text/plain; charset=utf-8"},\n                )\n                response.raise_for_status()\n        except Exception as exc:\n            raise ClipboardUnavailable("browser X11 clipboard helper is unavailable") from exc\n\n    async def clear_system_clipboard(self) -> None:\n        await self._set_system_clipboard("")\n\n    async def paste_text(self, locator: Locator, text: str, *, clear_existing: bool = True) -> None:\n        """Paste prepared text through the browser\'s real X11 clipboard."""\n        await self.ensure_page_focus()\n        try:\n            await locator.wait_for(state="visible", timeout=self._timeout_ms)\n            await self.click(locator, timeout_ms=self._timeout_ms)\n            if clear_existing:\n                await locator.press("Control+A")\n                await locator.press("Backspace")\n            await self._set_system_clipboard(text)\n            await locator.press("Control+V")\n\n            # ChatGPT\'s Lexical composer applies paste updates asynchronously.\n            # inner_text() returns immediately; it does not wait for the editor\n            # model to commit the pasted content. Keep the real X11 clipboard\n            # populated until the visible editor actually contains text.\n            rendered = ""\n            if text:\n                deadline = asyncio.get_running_loop().time() + (self._timeout_ms / 1000)\n                while asyncio.get_running_loop().time() < deadline:\n                    rendered = await locator.inner_text(timeout=self._timeout_ms)\n                    if rendered:\n                        break\n                    await asyncio.sleep(0.05)\n            else:\n                rendered = await locator.inner_text(timeout=self._timeout_ms)\n        except (ChatGPTUIError, ClipboardUnavailable):\n            raise\n        except Exception as exc:\n            raise ChatGPTUIError("could not paste benchmark prompt") from exc\n        finally:\n            # Do not leave benchmark text in the persistent desktop clipboard.\n            try:\n                await self.clear_system_clipboard()\n            except ClipboardUnavailable:\n                # Clearing failure is still a global infrastructure failure.\n                raise\n\n        if text and not rendered:\n            raise ChatGPTUIError("composer is empty after benchmark prompt paste")\n'}, 'apps/runner/src/gpt_trace_runner/chatgpt.py': {'source_sha256': 'd3a26102cdb2d24612a0f377235df24bef52a7509177531cf3362e16815131d3', 'target_sha256': '6d774f10c9b5e3b59f00576232470d1fe7c712a295d5bc4f735acb5b4b2057a6', 'target_text': 'from __future__ import annotations\n\nimport hashlib\nimport json\nimport re\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Any, Callable\n\nfrom playwright.async_api import Locator, Page, TimeoutError as PlaywrightTimeoutError\n\nfrom .conversation import (\n    ConversationClient,\n    assistant_model_slugs,\n    conversation_id_from_url,\n    extract_dataset_messages,\n    invoked_app_names,\n    validate_task_conversation,\n)\nfrom .exceptions import (\n    AmbiguousSubmission,\n    AppUnavailable,\n    AuthenticationRequired,\n    ChatGPTUIError,\n    ConcurrentTurnError,\n    EnvironmentDrift,\n    FatalUIState,\n    ModelMismatch,\n    RateLimited,\n    RecoveryIncomplete,\n    RequiredToolNotUsed,\n    SiteChallengeFailed,\n)\nfrom .interaction import InteractionGuard\nfrom .models import BenchmarkTask, BenchmarkTool, CapturedConversation\nfrom .site_guard import SiteGuard, first_visible\nfrom .stream import ConversationStream, is_conversation_stream_response\nfrom .tools import assert_apps_available, select_apps\nfrom .traffic import TrafficMonitor\nfrom .uploads import build_file_payloads\n\nSEND_SELECTORS = (\n    \'button[data-testid="send-button"]\',\n    "#composer-submit-button",\n    \'button[aria-label*="Send"]\',\n)\nATTACH_BUTTON_SELECTORS = (\n    \'button[data-testid="composer-plus-btn"]\',\n    \'button[aria-label*="Attach"]\',\n    \'button[aria-label*="Upload"]\',\n    \'button[data-testid*="attach"]\',\n)\nUPLOAD_MENU_LABELS = (\n    "Upload from computer", "Upload files", "Upload file", "Add photos & files",\n)\nNEW_CHAT_SELECTORS = (\n    \'a[data-testid="create-new-chat-button"]\',\n    \'button[data-testid="create-new-chat-button"]\',\n    \'a[aria-label*="New chat"]\',\n    \'button[aria-label*="New chat"]\',\n)\n\n\n@dataclass(slots=True)\nclass PreparedTurn:\n    task: BenchmarkTask\n\n\n@dataclass(slots=True)\nclass SubmittedTurn:\n    conversation_id: str\n    stream: ConversationStream\n    task: BenchmarkTask\n\n\nclass ChatGPTClient:\n    def __init__(\n        self,\n        page: Page,\n        *,\n        base_url: str,\n        conversation_turns: int,\n        turn_timeout_seconds: float,\n        stream_start_timeout_seconds: float,\n        tool_select_timeout_seconds: float,\n        upload_timeout_seconds: float,\n        site_ready_timeout_seconds: float,\n        challenge_timeout_seconds: float,\n        natural_snapshot_wait_seconds: float,\n        clipboard_url: str,\n        expected_model_slug: str,\n    ) -> None:\n        self._page = page\n        self._base_url = base_url.rstrip("/")\n        self._conversation = ConversationClient(page, turns=conversation_turns)\n        self._turn_timeout = turn_timeout_seconds\n        self._stream_start_timeout = stream_start_timeout_seconds\n        self._tool_select_timeout = tool_select_timeout_seconds\n        self._upload_timeout = upload_timeout_seconds\n        self._natural_snapshot_wait = natural_snapshot_wait_seconds\n        self._expected_model = expected_model_slug.strip()\n        self._traffic = TrafficMonitor(page, base_url=self._base_url)\n        self._interaction = InteractionGuard(\n            page, clipboard_url=clipboard_url, timeout_seconds=site_ready_timeout_seconds\n        )\n        self._site = SiteGuard(\n            page,\n            interaction=self._interaction,\n            traffic=self._traffic,\n            ready_timeout_seconds=site_ready_timeout_seconds,\n            challenge_timeout_seconds=challenge_timeout_seconds,\n        )\n        self._active_turn: SubmittedTurn | None = None\n        self._environment_baseline: dict[str, Any] | None = None\n        self._environment_hash: str | None = None\n\n    async def _navigate(self, url: str) -> None:\n        # BrowserClient applies cloakbrowser.human.patch_browser_async() to the\n        # connected Browser before this Page reaches ChatGPTClient. Calling the\n        # public Page.goto API here therefore goes through CloakBrowser\'s\n        # frame-aware/humanized wrapper. Never bypass it via private/original\n        # Playwright methods.\n        #\n        # Navigation and page readiness are separate invariants. "commit"\n        # proves the navigation response was received; SiteGuard or the auth\n        # waiter then handles login pages, interstitials/challenges and the\n        # final actionable ChatGPT UI.\n        try:\n            await self._page.goto(\n                url,\n                wait_until="commit",\n                timeout=60_000,\n            )\n        except PlaywrightTimeoutError as exc:\n            raise FatalUIState(\n                "ChatGPT navigation did not commit within 60 seconds"\n            ) from exc\n\n    async def goto_home(self) -> None:\n        await self._navigate(self._base_url)\n\n    async def _environment(self) -> dict[str, Any]:\n        try:\n            value = await self._page.evaluate(\n                """() => ({\n                    userAgent: navigator.userAgent,\n                    platform: navigator.platform,\n                    language: navigator.language,\n                    languages: Array.from(navigator.languages || []),\n                    hardwareConcurrency: navigator.hardwareConcurrency,\n                    maxTouchPoints: navigator.maxTouchPoints,\n                    screenWidth: screen.width,\n                    screenHeight: screen.height,\n                    colorDepth: screen.colorDepth,\n                    devicePixelRatio: window.devicePixelRatio,\n                    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,\n                    timezoneOffsetMin: new Date().getTimezoneOffset(),\n                })"""\n            )\n        except Exception as exc:\n            raise FatalUIState("could not read browser environment") from exc\n        if not isinstance(value, dict):\n            raise FatalUIState("browser environment probe returned invalid data")\n        return value\n\n    async def _check_environment(self) -> None:\n        current = await self._environment()\n        if self._environment_baseline is None:\n            self._environment_baseline = current\n            encoded = json.dumps(current, sort_keys=True, separators=(",", ":")).encode()\n            self._environment_hash = hashlib.sha256(encoded).hexdigest()\n            return\n        if current != self._environment_baseline:\n            raise EnvironmentDrift("browser environment changed during the batch")\n\n    async def prepare_session(self, *, fresh_home: bool = False) -> None:\n        if fresh_home or not self._page.url.startswith(self._base_url):\n            await self.goto_home()\n        await self._site.wait_ready()\n        await self._check_environment()\n\n    async def wait_until_authenticated(self, timeout_seconds: float) -> None:\n        """Use ChatGPT\'s own backend identity request as the auth oracle.\n\n        The supplied HAR shows authenticated frontend startup issuing:\n        GET /backend-api/me -> HTTP 200 with\n        {"object": "user", "id": "<non-empty>", ...}.\n        """\n        self._traffic.reset_auth_probe()\n\n        # TrafficMonitor is already listening before this navigation. Refreshing\n        # once makes an existing persistent session emit a fresh /backend-api/me;\n        # an unauthenticated session can then complete login normally in noVNC,\n        # after which the frontend emits the successful /me response.\n        if self._page.url.startswith(self._base_url):\n            try:\n                await self._page.reload(wait_until="commit", timeout=60_000)\n            except PlaywrightTimeoutError as exc:\n                raise FatalUIState(\n                    "ChatGPT authentication probe reload did not commit within 60 seconds"\n                ) from exc\n        else:\n            await self.goto_home()\n\n        await self._traffic.wait_for_authenticated_user(\n            timeout_seconds=timeout_seconds\n        )\n\n    async def _new_chat_if_needed(self) -> None:\n        old_id = conversation_id_from_url(self._page.url)\n        if old_id is None:\n            composer = await self._site.wait_ready()\n            try:\n                dirty = (await composer.inner_text()) != ""\n            except Exception as exc:\n                raise FatalUIState("could not inspect home composer state") from exc\n            if dirty:\n                await self.goto_home()\n                await self._site.wait_ready()\n            return\n\n        button = await first_visible(self._page, NEW_CHAT_SELECTORS)\n        if button is None:\n            raise FatalUIState("visible New chat control was not found")\n        await self._interaction.click(button)\n        try:\n            await self._page.wait_for_function(\n                "old => !location.pathname.startsWith(\'/c/\' + old)",\n                old_id,\n                timeout=int(self._stream_start_timeout * 1000),\n            )\n        except Exception as exc:\n            raise FatalUIState("New chat did not leave the previous conversation") from exc\n        await self._site.wait_ready()\n\n    async def _visible_exact_text(self, text: str, timeout_seconds: float) -> Locator | None:\n        import asyncio\n        deadline = asyncio.get_running_loop().time() + timeout_seconds\n        while asyncio.get_running_loop().time() < deadline:\n            locators = self._page.get_by_text(text, exact=True)\n            try:\n                for index in range(await locators.count()):\n                    candidate = locators.nth(index)\n                    if await candidate.is_visible():\n                        return candidate\n            except Exception as exc:\n                raise FatalUIState(f"could not inspect UI text {text!r}") from exc\n            await asyncio.sleep(0.1)\n        return None\n\n    async def _upload(self, attachments: tuple[Path, ...]) -> None:\n        if not attachments:\n            return\n        payloads = build_file_payloads(attachments)\n        attach = await first_visible(self._page, ATTACH_BUTTON_SELECTORS)\n        if attach is None:\n            raise FatalUIState("visible attachment control was not found")\n\n        chooser = None\n        try:\n            async with self._page.expect_file_chooser(timeout=3000) as info:\n                await self._interaction.click(attach)\n            chooser = await info.value\n        except PlaywrightTimeoutError:\n            pass\n\n        if chooser is None:\n            for label in UPLOAD_MENU_LABELS:\n                item = await self._visible_exact_text(label, min(2.0, self._upload_timeout))\n                if item is None:\n                    continue\n                try:\n                    async with self._page.expect_file_chooser(\n                        timeout=int(self._upload_timeout * 1000)\n                    ) as info:\n                        await self._interaction.click(item)\n                    chooser = await info.value\n                    break\n                except PlaywrightTimeoutError:\n                    continue\n        if chooser is None:\n            raise FatalUIState("attachment UI did not open a browser file chooser")\n        await chooser.set_files(payloads)\n        for attachment in attachments:\n            if await self._visible_exact_text(attachment.name, self._upload_timeout) is None:\n                raise FatalUIState(\n                    f"attachment did not become ready in ChatGPT: {attachment.name}"\n                )\n\n    async def verify_apps_available(\n        self,\n        tools: tuple[BenchmarkTool, ...],\n    ) -> None:\n        """Fail before benchmark execution if a required ChatGPT App is absent."""\n        await self._new_chat_if_needed()\n        editor = await self._site.wait_ready()\n        await assert_apps_available(\n            self._page,\n            editor=editor,\n            tools=tools,\n            interaction=self._interaction,\n            timeout_seconds=self._tool_select_timeout,\n        )\n        await self._site.wait_ready()\n\n    async def _compose(self, task: BenchmarkTask) -> None:\n        # Type the benchmark prompt through real keyboard events, then append\n        # Apps through ChatGPT\'s @ mention autocomplete. CloakBrowser owns\n        # humanization; the runner adds no artificial per-key delay.\n        #\n        # App mentions are structured composer nodes; never Ctrl+A after adding\n        # them or the mention may be deleted.\n        editor = await self._site.wait_ready()\n        await self._interaction.type_text(editor, task.prompt)\n        await select_apps(\n            self._page,\n            editor=editor,\n            tools=task.tools,\n            interaction=self._interaction,\n            timeout_seconds=self._tool_select_timeout,\n        )\n\n        expected_apps = len({\n            tool.name\n            for tool in task.tools\n            if tool.type == "app"\n        })\n        if expected_apps:\n            hints = await self._traffic.wait_for_submitted_app_hints(\n                expected_apps,\n                timeout_seconds=self._tool_select_timeout,\n            )\n            if len(hints) < expected_apps:\n                raise AppUnavailable(\n                    "accepted App mentions were not reflected in ChatGPT "\n                    "plugin system_hints: "\n                    f"expected at least {expected_apps} distinct App hint(s), "\n                    f"observed {len(hints)}"\n                )\n\n        await self._site.wait_ready()\n\n    async def prepare_task(self, task: BenchmarkTask) -> PreparedTurn:\n        if self._active_turn is not None:\n            raise ConcurrentTurnError("another ChatGPT turn is already active")\n        self._traffic.begin_task()\n        await self._check_environment()\n        try:\n            await self._new_chat_if_needed()\n            await self._upload(task.attachments)\n            await self._compose(task)\n            await self._interaction.ensure_page_focus()\n        except AppUnavailable:\n            raise\n        except (RateLimited, AuthenticationRequired, SiteChallengeFailed, FatalUIState):\n            raise\n        except Exception as exc:\n            raise FatalUIState(f"ChatGPT preparation failed: {exc}") from exc\n        return PreparedTurn(task=task)\n\n    async def _click_send(self, before_send: Callable[[], None]) -> None:\n        button = await first_visible(self._page, SEND_SELECTORS)\n        if button is None:\n            raise FatalUIState("visible enabled Send button was not found")\n        try:\n            if not await button.is_enabled():\n                raise FatalUIState("Send button is visible but disabled")\n        except FatalUIState:\n            raise\n        except Exception as exc:\n            raise FatalUIState("could not inspect Send button state") from exc\n        # Durable submission marker is committed only after a concrete Send\n        # control is found, immediately before the potentially-successful click.\n        before_send()\n        await self._interaction.click(button)\n\n    async def _wait_for_conversation_id(self) -> str:\n        try:\n            await self._page.wait_for_url(\n                re.compile(r"/c/[^/?#]+"),\n                timeout=int(self._stream_start_timeout * 1000),\n            )\n        except Exception as exc:\n            raise AmbiguousSubmission(\n                "conversation SSE started but no conversation URL was assigned"\n            ) from exc\n        value = conversation_id_from_url(self._page.url)\n        if not value:\n            raise AmbiguousSubmission("conversation URL has no usable ID")\n        return value\n\n    def _validate_submitted_model(self) -> None:\n        model = self._traffic.submitted_model\n        if self._expected_model and model != self._expected_model:\n            raise ModelMismatch(\n                f"frontend submitted model {model!r}; expected {self._expected_model!r}"\n            )\n        timezone = self._traffic.submitted_timezone\n        baseline_timezone = (\n            self._environment_baseline.get("timezone") if self._environment_baseline else None\n        )\n        if timezone and baseline_timezone and timezone != baseline_timezone:\n            raise EnvironmentDrift(\n                f"frontend timezone {timezone!r} != browser timezone {baseline_timezone!r}"\n            )\n        submitted_offset = self._traffic.submitted_timezone_offset_min\n        baseline_offset = (\n            self._environment_baseline.get("timezoneOffsetMin")\n            if self._environment_baseline else None\n        )\n        if (\n            submitted_offset is not None\n            and baseline_offset is not None\n            and submitted_offset != baseline_offset\n        ):\n            raise EnvironmentDrift(\n                f"frontend timezone offset {submitted_offset!r} != "\n                f"browser offset {baseline_offset!r}"\n            )\n\n    async def submit_task(self, prepared: PreparedTurn, *, before_send: Callable[[], None]) -> SubmittedTurn:\n        try:\n            async with self._page.expect_response(\n                is_conversation_stream_response,\n                timeout=int(self._stream_start_timeout * 1000),\n            ) as response_info:\n                await self._click_send(before_send)\n            response = await response_info.value\n        except Exception as exc:\n            if self._traffic.saw_backend_429:\n                raise RateLimited("ChatGPT returned HTTP 429 during submit") from exc\n            if self._traffic.saw_backend_403:\n                raise SiteChallengeFailed(\n                    "ChatGPT returned backend HTTP 403 and no conversation SSE was observed"\n                ) from exc\n            raise AmbiguousSubmission(\n                "no conversation SSE observed after Send; automatic resubmission is disabled"\n            ) from exc\n\n        self._traffic.validate_single_stream_request()\n        self._validate_submitted_model()\n        if not self._traffic.submitted_prompt_matches(prepared.task.prompt):\n            raise AmbiguousSubmission(\n                "frontend conversation POST prompt differs from benchmark prompt"\n            )\n        conversation_id = await self._wait_for_conversation_id()\n        submitted = SubmittedTurn(\n            conversation_id=conversation_id,\n            stream=ConversationStream(response, timeout_seconds=self._turn_timeout),\n            task=prepared.task,\n        )\n        self._active_turn = submitted\n        return submitted\n\n    def _validate_required_tools(self, task: BenchmarkTask, messages: list[dict]) -> set[str]:\n        used = invoked_app_names(messages)\n        folded = {name.casefold() for name in used}\n        missing = [\n            tool.name for tool in task.tools\n            if tool.required and tool.name.casefold() not in folded\n        ]\n        if missing:\n            raise RequiredToolNotUsed(\n                "required ChatGPT app(s) were not invoked: " + ", ".join(missing)\n            )\n        return used\n\n    def _validate_message_models(self, messages: list[dict]) -> set[str]:\n        slugs = assistant_model_slugs(messages)\n        if self._expected_model:\n            unexpected = sorted(slug for slug in slugs if slug != self._expected_model)\n            if unexpected:\n                raise ModelMismatch(\n                    f"assistant messages contain unexpected model slug(s): {unexpected}; "\n                    f"expected only {self._expected_model!r}"\n                )\n        return slugs\n\n    def _validated_messages(self, conversation: dict[str, Any], task: BenchmarkTask) -> list[dict]:\n        messages = extract_dataset_messages(conversation)\n        validate_task_conversation(messages, task.prompt)\n        self._validate_message_models(messages)\n        return messages\n\n    async def wait_for_completion(self, submitted: SubmittedTurn) -> CapturedConversation:\n        if self._active_turn is not submitted:\n            raise ConcurrentTurnError("submitted turn is not active")\n        try:\n            stream_result = await submitted.stream.wait()\n            if stream_result.conversation_id != submitted.conversation_id:\n                raise AmbiguousSubmission(\n                    "conversation ID mismatch between browser URL and completed SSE"\n                )\n            self._traffic.validate_single_stream_request()\n            self._validate_submitted_model()\n            await self._check_environment()\n            if self._traffic.saw_backend_429:\n                raise RateLimited("ChatGPT returned HTTP 429 during the turn")\n\n            conversation = await self._traffic.natural_snapshot(\n                submitted.conversation_id,\n                wait_seconds=self._natural_snapshot_wait,\n            )\n            messages = None\n            if conversation is not None:\n                try:\n                    messages = self._validated_messages(conversation, submitted.task)\n                    self._traffic.mark_natural_snapshot_used()\n                except Exception:\n                    messages = None\n            if messages is None:\n                self._traffic.mark_fallback_snapshot()\n                conversation = await self._conversation.fetch(submitted.conversation_id)\n                messages = self._validated_messages(conversation, submitted.task)\n\n            used_apps = self._validate_required_tools(submitted.task, messages)\n            metadata = stream_result.runtime_metadata()\n            metadata.update(self._traffic.runtime_metadata())\n            metadata.update({\n                "recovered": False,\n                "environment_sha256": self._environment_hash,\n                "expected_model": self._expected_model,\n                "requested_tools": [\n                    {"type": t.type, "name": t.name, "required": t.required}\n                    for t in submitted.task.tools\n                ],\n                "used_apps": sorted(used_apps),\n            })\n            return CapturedConversation(submitted.conversation_id, messages, metadata)\n        finally:\n            self._active_turn = None\n\n    async def recover(self, conversation_id: str, *, task: BenchmarkTask) -> CapturedConversation:\n        if self._active_turn is not None:\n            raise ConcurrentTurnError("cannot recover while another turn is active")\n        await self._navigate(f"{self._base_url}/c/{conversation_id}")\n        await self._site.wait_ready()\n        await self._check_environment()\n        conversation = await self._conversation.fetch(conversation_id)\n        try:\n            messages = self._validated_messages(conversation, task)\n        except Exception as exc:\n            raise RecoveryIncomplete(\n                f"existing conversation cannot be safely recovered: {exc}"\n            ) from exc\n        used_apps = self._validate_required_tools(task, messages)\n        return CapturedConversation(\n            conversation_id,\n            messages,\n            {\n                "recovered": True,\n                "stream_observed": False,\n                "environment_sha256": self._environment_hash,\n                "expected_model": self._expected_model,\n                "requested_tools": [\n                    {"type": t.type, "name": t.name, "required": t.required}\n                    for t in task.tools\n                ],\n                "used_apps": sorted(used_apps),\n            },\n        )\n\n    async def recover_current_candidate(self, *, task: BenchmarkTask) -> CapturedConversation:\n        conversation_id = conversation_id_from_url(self._page.url)\n        if not conversation_id:\n            raise RecoveryIncomplete(\n                "submission may have happened but current browser URL has no conversation ID"\n            )\n        return await self.recover(conversation_id, task=task)\n'}, 'apps/runner/src/gpt_trace_runner/traffic.py': {'source_sha256': 'd1876ac5e27b28478a80b1b9e099dfb66c9c3f1827b21ed39d33cb92f2910e25', 'target_sha256': 'e546adaba90212a9c34c23644af64395ceaf0b64529ea96d952e9ccfb4c6bc52', 'target_text': 'from __future__ import annotations\n\nimport asyncio\nimport json\nimport re\nfrom dataclasses import asdict, dataclass\nfrom typing import Any\nfrom urllib.parse import urlparse\n\nfrom playwright.async_api import Page, Response\n\nfrom .conversation import benchmark_text_matches\n\n\n_CONVERSATION_SNAPSHOT = re.compile(r"^/backend-api/conversations/([^/]+)$")\n\n\n@dataclass(slots=True)\nclass TrafficStats:\n    chatgpt_requests: int = 0\n    backend_requests: int = 0\n    sentinel_requests: int = 0\n    conversation_requests: int = 0\n    conversation_prepare_requests: int = 0\n    conversation_stream_requests: int = 0\n    requests_failed: int = 0\n    responses_403: int = 0\n    responses_429: int = 0\n    responses_5xx: int = 0\n    challenge_seen: bool = False\n    challenge_resolved: bool = False\n    natural_snapshot_used: bool = False\n    fallback_snapshot_used: bool = False\n    submitted_model: str | None = None\n    submitted_timezone: str | None = None\n    submitted_timezone_offset_min: int | None = None\n    submitted_app_hints: tuple[str, ...] = ()\n\n\nclass TrafficMonitor:\n    """Count browser traffic without retaining security headers, cookies, or bodies."""\n\n    def __init__(self, page: Page, *, base_url: str) -> None:\n        self._base_host = urlparse(base_url).hostname or "chatgpt.com"\n        self._generation = 0\n        self._stats = TrafficStats()\n        self._snapshots: dict[str, Response] = {}\n        self._snapshot_events: dict[str, asyncio.Event] = {}\n        self._request_generation: dict[int, int] = {}\n        self._task_403 = False\n        self._sticky_429 = False\n        self._submitted_user_message: dict[str, Any] | None = None\n        page.on("request", self._on_request)\n        page.on("response", self._on_response)\n        page.on("requestfailed", self._on_request_failed)\n\n    def begin_task(self) -> None:\n        self._generation += 1\n        self._stats = TrafficStats()\n        self._snapshots = {}\n        self._snapshot_events = {}\n        self._task_403 = False\n        self._submitted_user_message = None\n        # sticky 429 intentionally survives task boundaries.\n\n    def _is_chatgpt_host(self, url: str) -> bool:\n        host = urlparse(url).hostname or ""\n        return (\n            host == self._base_host\n            or host.endswith("." + self._base_host)\n            or host == "openai.com"\n            or host.endswith(".openai.com")\n        )\n\n    @staticmethod\n    def _is_backend_path(path: str) -> bool:\n        return path.startswith("/backend-api/") or path.startswith("/backend-anon/")\n\n    def _on_request(self, request) -> None:\n        if not self._is_chatgpt_host(request.url):\n            return\n        self._request_generation[id(request)] = self._generation\n        path = urlparse(request.url).path.rstrip("/")\n        self._stats.chatgpt_requests += 1\n        if self._is_backend_path(path):\n            self._stats.backend_requests += 1\n        if "/sentinel/" in path:\n            self._stats.sentinel_requests += 1\n        if "/conversation" in path:\n            self._stats.conversation_requests += 1\n        if path == "/backend-api/f/conversation/prepare":\n            self._stats.conversation_prepare_requests += 1\n\n        if (\n            request.method.upper() == "POST"\n            and path in {\n                "/backend-api/conversation/init",\n                "/backend-api/f/conversation/prepare",\n            }\n        ):\n            try:\n                payload = request.post_data_json\n                if isinstance(payload, dict):\n                    hints = payload.get("system_hints")\n                    if isinstance(hints, list):\n                        observed = {\n                            hint\n                            for hint in hints\n                            if isinstance(hint, str)\n                            and hint.startswith("plugin:asdk_app_")\n                        }\n                        if observed:\n                            combined = set(self._stats.submitted_app_hints)\n                            combined.update(observed)\n                            self._stats.submitted_app_hints = tuple(sorted(combined))\n            except Exception:\n                pass\n        if path == "/backend-api/f/conversation" and request.method.upper() == "POST":\n            self._stats.conversation_stream_requests += 1\n            try:\n                payload = request.post_data_json\n                if isinstance(payload, dict):\n                    model = payload.get("model")\n                    if isinstance(model, str):\n                        self._stats.submitted_model = model\n                    timezone = payload.get("timezone")\n                    if isinstance(timezone, str):\n                        self._stats.submitted_timezone = timezone\n                    offset = payload.get("timezone_offset_min")\n                    if isinstance(offset, int):\n                        self._stats.submitted_timezone_offset_min = offset\n                    messages = payload.get("messages")\n                    if isinstance(messages, list):\n                        for message in messages:\n                            if not isinstance(message, dict):\n                                continue\n                            author = message.get("author")\n                            if isinstance(author, dict) and author.get("role") == "user":\n                                self._submitted_user_message = message\n                                break\n            except Exception:\n                pass\n\n    def _belongs_to_current(self, request) -> bool:\n        return self._request_generation.get(id(request), self._generation) == self._generation\n\n    def _on_response(self, response: Response) -> None:\n        if not self._is_chatgpt_host(response.url):\n            return\n        current = self._belongs_to_current(response.request)\n        path = urlparse(response.url).path.rstrip("/")\n        if self._is_backend_path(path):\n            if response.status == 429:\n                self._sticky_429 = True\n                if current:\n                    self._stats.responses_429 += 1\n            elif response.status == 403 and current:\n                self._task_403 = True\n                self._stats.responses_403 += 1\n            elif response.status >= 500 and current:\n                self._stats.responses_5xx += 1\n\n        if current:\n            match = _CONVERSATION_SNAPSHOT.match(path)\n            if match and response.request.method.upper() == "GET" and 200 <= response.status < 300:\n                conversation_id = match.group(1)\n                self._snapshots[conversation_id] = response\n                event = self._snapshot_events.get(conversation_id)\n                if event is not None:\n                    event.set()\n        self._request_generation.pop(id(response.request), None)\n\n    def _on_request_failed(self, request) -> None:\n        if self._is_chatgpt_host(request.url) and self._belongs_to_current(request):\n            self._stats.requests_failed += 1\n        self._request_generation.pop(id(request), None)\n\n    @property\n    def saw_backend_403(self) -> bool:\n        return self._task_403\n\n    @property\n    def saw_backend_429(self) -> bool:\n        return self._sticky_429\n\n    @property\n    def submitted_model(self) -> str | None:\n        return self._stats.submitted_model\n\n    @property\n    def submitted_timezone(self) -> str | None:\n        return self._stats.submitted_timezone\n\n    @property\n    def submitted_timezone_offset_min(self) -> int | None:\n        return self._stats.submitted_timezone_offset_min\n\n    def submitted_prompt_matches(self, prompt: str) -> bool:\n        message = self._submitted_user_message\n        return isinstance(message, dict) and benchmark_text_matches(message, prompt)\n\n    @property\n    def submitted_app_hints(self) -> tuple[str, ...]:\n        return self._stats.submitted_app_hints\n\n    async def wait_for_submitted_app_hints(\n        self,\n        minimum_count: int,\n        *,\n        timeout_seconds: float,\n    ) -> tuple[str, ...]:\n        deadline = asyncio.get_running_loop().time() + timeout_seconds\n        while asyncio.get_running_loop().time() < deadline:\n            current = self._stats.submitted_app_hints\n            if len(current) >= minimum_count:\n                return current\n            await asyncio.sleep(0.05)\n        return self._stats.submitted_app_hints\n\n    @property\n    def conversation_stream_requests(self) -> int:\n        return self._stats.conversation_stream_requests\n\n    def mark_challenge_seen(self) -> None:\n        self._stats.challenge_seen = True\n\n    def mark_challenge_resolved(self) -> None:\n        self._stats.challenge_seen = True\n        self._stats.challenge_resolved = True\n\n    def mark_natural_snapshot_used(self) -> None:\n        self._stats.natural_snapshot_used = True\n\n    def mark_fallback_snapshot(self) -> None:\n        self._stats.fallback_snapshot_used = True\n\n    def validate_single_stream_request(self) -> None:\n        if self._stats.conversation_stream_requests != 1:\n            from .exceptions import AmbiguousSubmission\n            raise AmbiguousSubmission(\n                "expected exactly one frontend POST /backend-api/f/conversation; "\n                f"observed {self._stats.conversation_stream_requests}"\n            )\n\n    async def natural_snapshot(self, conversation_id: str, *, wait_seconds: float) -> dict[str, Any] | None:\n        response = self._snapshots.get(conversation_id)\n        if response is None and wait_seconds > 0:\n            event = self._snapshot_events.setdefault(conversation_id, asyncio.Event())\n            try:\n                await asyncio.wait_for(event.wait(), timeout=wait_seconds)\n            except TimeoutError:\n                return None\n            response = self._snapshots.get(conversation_id)\n        if response is None:\n            return None\n        try:\n            payload = json.loads((await response.body()).decode("utf-8"))\n        except Exception:\n            return None\n        if not isinstance(payload, dict) or not isinstance(payload.get("messages"), list):\n            return None\n        return payload\n\n    def runtime_metadata(self) -> dict[str, Any]:\n        return asdict(self._stats)\n'}, 'apps/runner/tests/test_app_picker_invariants.py': {'source_sha256': '4b218c17f65a617fd6b65e9961c619860b691550e36b8d714cfe5e95ecb8e4a8', 'target_sha256': 'df757fe90f5afe80c3462a812983d89f0828c7ad9a340aad61f513f46058a706', 'target_text': 'from pathlib import Path\n\n\ndef _source(name: str) -> str:\n    return (\n        Path(__file__).parents[1]\n        / "src"\n        / "gpt_trace_runner"\n        / name\n    ).read_text(encoding="utf-8")\n\n\ndef test_app_selection_uses_keyboard_acceptance_not_popup_dom() -> None:\n    source = _source("tools.py")\n    assert \'await page.keyboard.type("@")\' in source\n    assert "await page.keyboard.type(tool.name)" in source\n    assert \'await page.keyboard.press("Enter")\' in source\n    assert "_find_mention_result" not in source\n    assert "_POPUP_ROOTS" not in source\n    assert "delay=20" not in source\n\n\ndef test_app_selection_requires_raw_to_structured_mention_transition() -> None:\n    source = _source("tools.py")\n    assert \'raw_mention = f"@{tool.name}"\' in source\n    assert "typed_rendered.rstrip().endswith(raw_mention)" in source\n    assert "rendered != typed_rendered" in source\n    assert "tail.endswith(tool.name)" in source\n    assert "not tail.endswith(raw_mention)" in source\n\n\ndef test_chatgpt_compose_types_prompt_before_selecting_apps() -> None:\n    source = _source("chatgpt.py")\n    compose = source.split("async def _compose", 1)[1].split(\n        "async def prepare_task", 1\n    )[0]\n    assert "self._interaction.type_text(editor, task.prompt)" in compose\n    assert "await select_apps(" in compose\n    assert compose.index("type_text") < compose.index("select_apps")\n    assert "paste_text(editor, task.prompt)" not in compose\n    assert "wait_for_submitted_app_hints" in compose\n'}, 'apps/runner/tests/test_interaction.py': {'source_sha256': 'fda02235f2efcc221a90b16fcc0368c0928e1538296272ac1a9212f53e7a17cd', 'target_sha256': '9ab8ad6af6e9d5289e574d0bb7f6b4af4e77c016a17fa42a1bb8e534f35d17de', 'target_text': 'from __future__ import annotations\n\nimport asyncio\nimport pytest\n\nfrom gpt_trace_runner.interaction import InteractionGuard\n\n\nclass FakeKeyboard:\n    def __init__(self):\n        self.events = []\n        self.locator = None\n\n    async def type(self, text):\n        self.events.append(("type", text))\n        if self.locator is not None:\n            self.locator.rendered += text\n\n    async def press(self, key):\n        self.events.append(("press", key))\n        if key == "Shift+Enter" and self.locator is not None:\n            self.locator.rendered += "\\n"\n\n\nclass FakePage:\n    def __init__(self, state):\n        self.state = state\n        self.bring_calls = 0\n        self.wait_calls = 0\n        self.keyboard = FakeKeyboard()\n\n    async def evaluate(self, expression):\n        return self.state\n\n    async def bring_to_front(self):\n        self.bring_calls += 1\n\n    async def wait_for_function(self, expression, timeout):\n        self.wait_calls += 1\n\n\n@pytest.mark.asyncio\nasync def test_focus_is_not_forced_when_page_is_already_active() -> None:\n    page = FakePage({"visible": True, "focused": True})\n    guard = InteractionGuard(\n        page,\n        clipboard_url="http://browser:8765/clipboard",\n        timeout_seconds=1,\n    )\n    await guard.ensure_page_focus()\n    assert page.bring_calls == 0\n    assert page.wait_calls == 0\n\n\n@pytest.mark.asyncio\nasync def test_focus_is_requested_only_when_needed() -> None:\n    page = FakePage({"visible": True, "focused": False})\n    guard = InteractionGuard(\n        page,\n        clipboard_url="http://browser:8765/clipboard",\n        timeout_seconds=1,\n    )\n    await guard.ensure_page_focus()\n    assert page.bring_calls == 1\n    assert page.wait_calls == 1\n\n\nclass FakeLocator:\n    def __init__(self, holder):\n        self.holder = holder\n        self.rendered = ""\n    async def wait_for(self, **kwargs): pass\n    async def is_enabled(self): return True\n    async def click(self, **kwargs): pass\n    async def press(self, key):\n        if key == "Control+A":\n            self.holder["select_all"] = True\n        elif key == "Backspace" and self.holder.get("select_all"):\n            self.rendered = ""\n        elif key == "Control+V":\n            self.rendered += self.holder.get("clipboard", "")\n    async def inner_text(self, **kwargs): return self.rendered\n\n\n@pytest.mark.asyncio\nasync def test_paste_preserves_exact_spaces_and_clears_clipboard() -> None:\n    holder = {"clipboard": ""}\n    page = FakePage({"visible": True, "focused": True})\n    guard = InteractionGuard(page, clipboard_url="http://browser:8765/clipboard", timeout_seconds=1)\n    calls = []\n    async def set_clipboard(value):\n        holder["clipboard"] = value\n        calls.append(value)\n    guard._set_system_clipboard = set_clipboard\n    locator = FakeLocator(holder)\n    await guard.paste_text(locator, "  exact  ")\n    assert locator.rendered == "  exact  "\n    assert calls == ["  exact  ", ""]\n\n\nclass DelayedPasteLocator(FakeLocator):\n    async def press(self, key):\n        if key != "Control+V":\n            await super().press(key)\n            return\n\n        async def commit():\n            await asyncio.sleep(0.05)\n            self.rendered += self.holder.get("clipboard", "")\n\n        asyncio.create_task(commit())\n\n\n@pytest.mark.asyncio\nasync def test_paste_waits_for_async_composer_commit_before_clearing_clipboard() -> None:\n    holder = {"clipboard": ""}\n    page = FakePage({"visible": True, "focused": True})\n    guard = InteractionGuard(\n        page,\n        clipboard_url="http://browser:8765/clipboard",\n        timeout_seconds=1,\n    )\n    calls = []\n\n    async def set_clipboard(value):\n        holder["clipboard"] = value\n        calls.append(value)\n\n    guard._set_system_clipboard = set_clipboard\n    locator = DelayedPasteLocator(holder)\n\n    await guard.paste_text(locator, "delayed prompt")\n\n    assert locator.rendered == "delayed prompt"\n    assert calls == ["delayed prompt", ""]\n\n\n@pytest.mark.asyncio\nasync def test_type_text_uses_real_keyboard_and_shift_enter() -> None:\n    page = FakePage({"visible": True, "focused": True})\n    guard = InteractionGuard(\n        page,\n        clipboard_url="http://browser:8765/clipboard",\n        timeout_seconds=1,\n    )\n    locator = FakeLocator({})\n    page.keyboard.locator = locator\n\n    await guard.type_text(locator, "first line\\nsecond line")\n\n    assert locator.rendered == "first line\\nsecond line"\n    assert page.keyboard.events == [\n        ("type", "first line"),\n        ("press", "Shift+Enter"),\n        ("type", "second line"),\n    ]\n\n\n@pytest.mark.asyncio\nasync def test_type_text_does_not_use_clipboard() -> None:\n    page = FakePage({"visible": True, "focused": True})\n    guard = InteractionGuard(\n        page,\n        clipboard_url="http://browser:8765/clipboard",\n        timeout_seconds=1,\n    )\n    locator = FakeLocator({})\n    page.keyboard.locator = locator\n\n    async def forbidden_clipboard(_value):\n        raise AssertionError("keyboard prompt entry must not touch clipboard")\n\n    guard._set_system_clipboard = forbidden_clipboard\n    await guard.type_text(locator, "prompt")\n    assert locator.rendered == "prompt"\n'}, 'apps/runner/tests/test_traffic.py': {'source_sha256': 'b7862b0bcca7c099d1eda4159c9e478417dce08de4f2a8f706863a1d65cf3db4', 'target_sha256': '43fb6990b3f7d47e56536fd34c50387a92d7f6f9779394bb79ab54069e569ae4', 'target_text': 'import json\n\nimport pytest\n\nfrom gpt_trace_runner.exceptions import AmbiguousSubmission\nfrom gpt_trace_runner.traffic import TrafficMonitor\n\n\nclass FakePage:\n    def __init__(self) -> None:\n        self.handlers = {}\n\n    def on(self, name, callback):\n        self.handlers[name] = callback\n\n\nclass FakeRequest:\n    def __init__(self, url: str, method: str = "GET", payload=None) -> None:\n        self.url = url\n        self.method = method\n        self.post_data_json = payload\n\n\nclass FakeResponse:\n    def __init__(self, url: str, *, status: int = 200, method: str = "GET", payload=None, request=None) -> None:\n        self.url = url\n        self.status = status\n        self.request = request or FakeRequest(url, method)\n        self._payload = payload or {}\n\n    async def body(self):\n        return json.dumps(self._payload).encode()\n\n\n@pytest.mark.asyncio\nasync def test_natural_snapshot_is_observed_without_marking_used_until_validated() -> None:\n    page = FakePage()\n    monitor = TrafficMonitor(page, base_url="https://chatgpt.com")\n    monitor.begin_task()\n    request = FakeRequest("https://chatgpt.com/backend-api/conversations/conv-1?num_turns=100")\n    response = FakeResponse(request.url, payload={"messages": [{"id": "m1"}]}, request=request)\n    page.handlers["request"](request)\n    page.handlers["response"](response)\n    payload = await monitor.natural_snapshot("conv-1", wait_seconds=0)\n    assert payload == {"messages": [{"id": "m1"}]}\n    assert monitor.runtime_metadata()["natural_snapshot_used"] is False\n    monitor.mark_natural_snapshot_used()\n    assert monitor.runtime_metadata()["natural_snapshot_used"] is True\n\n\ndef test_429_is_sticky_across_task_boundaries() -> None:\n    page = FakePage()\n    monitor = TrafficMonitor(page, base_url="https://chatgpt.com")\n    monitor.begin_task()\n    request = FakeRequest("https://chatgpt.com/backend-api/foo")\n    page.handlers["request"](request)\n    page.handlers["response"](FakeResponse(request.url, status=429, request=request))\n    assert monitor.saw_backend_429 is True\n    monitor.begin_task()\n    assert monitor.saw_backend_429 is True\n\n\ndef test_late_response_is_not_counted_in_next_task() -> None:\n    page = FakePage()\n    monitor = TrafficMonitor(page, base_url="https://chatgpt.com")\n    monitor.begin_task()\n    request = FakeRequest("https://chatgpt.com/backend-api/foo")\n    page.handlers["request"](request)\n    monitor.begin_task()\n    page.handlers["response"](FakeResponse(request.url, status=403, request=request))\n    assert monitor.runtime_metadata()["responses_403"] == 0\n\n\ndef test_conversation_post_extracts_only_audited_runtime_fields() -> None:\n    page = FakePage()\n    monitor = TrafficMonitor(page, base_url="https://chatgpt.com")\n    monitor.begin_task()\n    request = FakeRequest(\n        "https://chatgpt.com/backend-api/f/conversation",\n        "POST",\n        {\n            "model": "gpt-5-6-thinking",\n            "timezone": "Europe/Zurich",\n            "timezone_offset_min": 120,\n            "secret": "not-kept",\n        },\n    )\n    page.handlers["request"](request)\n    meta = monitor.runtime_metadata()\n    assert meta["submitted_model"] == "gpt-5-6-thinking"\n    assert meta["submitted_timezone"] == "Europe/Zurich"\n    assert "secret" not in meta\n\n\ndef test_exactly_one_conversation_post_required() -> None:\n    page = FakePage()\n    monitor = TrafficMonitor(page, base_url="https://chatgpt.com")\n    monitor.begin_task()\n    with pytest.raises(AmbiguousSubmission):\n        monitor.validate_single_stream_request()\n    for _ in range(2):\n        page.handlers["request"](FakeRequest("https://chatgpt.com/backend-api/f/conversation", "POST", {}))\n    with pytest.raises(AmbiguousSubmission):\n        monitor.validate_single_stream_request()\n\n\ndef test_failed_request_is_cleaned_and_counted() -> None:\n    page = FakePage()\n    monitor = TrafficMonitor(page, base_url="https://chatgpt.com")\n    monitor.begin_task()\n    request = FakeRequest("https://chatgpt.com/backend-api/foo")\n    page.handlers["request"](request)\n    page.handlers["requestfailed"](request)\n    assert monitor.runtime_metadata()["requests_failed"] == 1\n\n\ndef test_conversation_post_prompt_with_configured_app_mention_matches_benchmark() -> None:\n    page = FakePage()\n    monitor = TrafficMonitor(page, base_url="https://chatgpt.com")\n    monitor.begin_task()\n    request = FakeRequest(\n        "https://chatgpt.com/backend-api/f/conversation",\n        "POST",\n        {\n            "model": "gpt-5-6-thinking",\n            "timezone": "Europe/Zurich",\n            "timezone_offset_min": -120,\n            "messages": [\n                {\n                    "author": {"role": "user"},\n                    "content": {"content_type": "text", "parts": ["@GitHub Connector inspect repo"]},\n                    "metadata": {\n                        "serialization_metadata": {\n                            "custom_symbol_offsets": [\n                                {"symbol": "ecosystemMention", "startIndex": 0, "endIndex": 17}\n                            ]\n                        }\n                    },\n                }\n            ],\n        },\n    )\n    page.handlers["request"](request)\n    assert monitor.submitted_prompt_matches("inspect repo") is True\n    assert monitor.submitted_prompt_matches("inspect  repo") is False\n    assert monitor.submitted_timezone_offset_min == -120\n\n\n@pytest.mark.asyncio\nasync def test_app_system_hints_are_captured_from_init_and_prepare() -> None:\n    page = FakePage()\n    monitor = TrafficMonitor(page, base_url="https://chatgpt.com")\n    monitor.begin_task()\n\n    page.handlers["request"](\n        FakeRequest(\n            "https://chatgpt.com/backend-api/conversation/init",\n            "POST",\n            {\n                "system_hints": [\n                    "plugin:asdk_app_workspace",\n                    "unrelated:hint",\n                ]\n            },\n        )\n    )\n    page.handlers["request"](\n        FakeRequest(\n            "https://chatgpt.com/backend-api/f/conversation/prepare",\n            "POST",\n            {\n                "system_hints": [\n                    "plugin:asdk_app_workspace",\n                    "plugin:asdk_app_browser",\n                ]\n            },\n        )\n    )\n\n    hints = await monitor.wait_for_submitted_app_hints(2, timeout_seconds=0.1)\n    assert hints == (\n        "plugin:asdk_app_browser",\n        "plugin:asdk_app_workspace",\n    )\n    assert monitor.runtime_metadata()["submitted_app_hints"] == hints\n'}}


def sha256_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def atomic_write(path: Path, text: str) -> None:
    mode = path.stat().st_mode & 0o777
    fd, raw = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    tmp = Path(raw)
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        tmp.unlink(missing_ok=True)


def main() -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Switch ChatGPT prompt/App composition to Cloak-humanized keyboard events "
            "and capture plugin system_hints. Modifies existing runner files only."
        )
    )
    parser.add_argument("repo", nargs="?", default=".")
    args = parser.parse_args()
    root = Path(args.repo).resolve()

    changes = []
    for rel, spec in FILES.items():
        path = root / rel
        if not path.is_file():
            raise RuntimeError(f"missing expected file: {rel}")
        current = path.read_text(encoding="utf-8")
        current_sha = sha256_text(current)

        if current_sha == spec["target_sha256"]:
            continue
        if current_sha != spec["source_sha256"]:
            raise RuntimeError(
                f"refusing to overwrite unverified local state: {rel}\n"
                f"expected inspected sha256={spec['source_sha256']}\n"
                f"actual sha256={current_sha}"
            )

        compile(spec["target_text"], rel, "exec")
        changes.append((path, spec["target_text"]))

    # All files are verified before the first write: either the inspected source
    # or the exact target state. No partial patch if one file has drifted.
    for path, target in changes:
        atomic_write(path, target)

    print(f"modified existing files: {len(changes)}")
    for path, _ in changes:
        print(" -", path.relative_to(root))
    print("created repo files: 0")
    print("deleted repo files: 0")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(f"patch failed: {exc}", file=sys.stderr)
        raise SystemExit(1)
